 create database Customer_beahvior_vs;
go

use Customer_beahvior_vs;
go
select * from Customer_Behavior
--Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount_USD) as total_revenue
from Customer_Behavior
group by Gender
order by total_revenue DESC

----Q2. Which customers used a discount but still spent more than the average purchase amount?
select [Customer ID],[Discount Applied],purchase_amount_USD
from Customer_Behavior
where purchase_amount_USD >(select AVG(purchase_amount_USD) as avg_purchase_amount from Customer_Behavior)
and [Discount Applied] = 'Yes'

--Q3. Which are the top 5 products with the highest average review rating?
select top 5 [Item Purchased] ,round(AVG([Review Rating]),2) as average_review_rating
from Customer_Behavior
group by [Item Purchased] 
order by average_review_rating DESC

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select [Shipping Type],AVG(Purchase_Amount_USD) as avg_purchase_amount
from Customer_Behavior
where [shipping Type] = 'Standard' or [Shipping Type] = 'Express'
group by [Shipping Type]
order by avg_purchase_amount DESC

--Q5. Do subscribed customers spend more? 
--Compare average spend and total revenue between subscribers and non-subscribers.
select [Subscription Status],sum(purchase_amount_USD) as total_Revenue,
avg(purchase_amount_USD) as avg_spend
from Customer_Behavior
group by [Subscription Status] 
order by total_Revenue DESC,avg_spend DESC

----Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select top(5) [Item Purchased],
round(100 * sum(case when [discount Applied] = 'yes' then 1 else 0 end)/COUNT(*),2) as discount_rate 
from Customer_Behavior
group by [Item Purchased]
order by discount_rate DESC

--Q7. Segment customers into New, Returning, and Loyal based on their total 
--number of previous purchases, and show the count of each segment.
select Segment_Customers,
count(segment_Customers) as num_seg_cust
from(
	select [Customer ID],sum([Previous Purchases]) as total_prev_purchase,
	case when sum([Previous Purchases]) between 1 and 10 then 'New'
	when sum([Previous Purchases]) between 11 and 35 then 'Returning'
	else 'loyal' End As Segment_Customers
	from Customer_Behavior
	group by [Customer ID]
	) as sub_table
group by Segment_Customers
order by num_seg_cust DESC

--Q8. What are the top 3 most purchased products within each category?
select top(3) Category,
count([Customer ID]) as total_orders,[Item Purchased]
from Customer_Behavior
group by Category,[Item Purchased]
order by total_orders DESC

----Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select [Subscription Status],count([Customer ID]) as repeat_buyers
from Customer_Behavior
where [Previous Purchases] >5
group by [Subscription Status]
order by repeat_buyers DESC

--Q10. What is the revenue contribution of each age group?
select case when age between 18 and 25 then 'youth'
when age between 26 and 40 then 'semi_adult'
else 'Adult' END as Segement_age,
sum([Purchase_Amount_USD]) as total_revenue
from Customer_Behavior
group by case when age between 18 and 25 then 'youth'
when age between 26 and 40 then 'semi_adult'
else 'Adult' END
order by total_revenue DESC



